-- Run as project owner. Return check labels only, no identities or records.
with checks(check_name,ok) as(values
 ('is_approved_operations',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='is_approved_operations' and p.oid=to_regprocedure('public.is_approved_operations()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='e1fbe6f682f94c1b21c21ed5567dc0f5')),false)),
 ('nigraan_is_judge_admin',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_is_judge_admin' and p.oid=to_regprocedure('public.nigraan_is_judge_admin()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='1ac725896b70e5e9c83e2ed6ed3a3890')),false)),
 ('nigraan_is_permanent_operations',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_is_permanent_operations' and p.oid=to_regprocedure('public.nigraan_is_permanent_operations()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='f73ad124cf7222569038b63d7f7937f0')),false)),
 ('nigraan_has_operations_access',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_has_operations_access' and p.oid=to_regprocedure('public.nigraan_has_operations_access()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='f5b6d2c65158b5bfdae6034edca3095e')),false)),
 ('nigraan_claim_judge_email',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_claim_judge_email' and p.oid=to_regprocedure('public.nigraan_claim_judge_email(uuid)') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='4fb0db7e35605d80abbfd1fa9698af27')),false)),
 ('nigraan_review_judge_access',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_review_judge_access' and p.oid=to_regprocedure('public.nigraan_review_judge_access(uuid,text,integer,timestamptz)') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='ed426b68ed21377d4d790a2808589e4b')),false)),
 ('nigraan_decide_judge_access',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_decide_judge_access' and p.oid=to_regprocedure('public.nigraan_decide_judge_access(uuid,text)') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='e250192676b657f61b2a738040a68a02')),false)),
 ('nigraan_operations_access_context',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_operations_access_context' and p.oid=to_regprocedure('public.nigraan_operations_access_context()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='3ff26111313c80ea05a22f3ea29732d5')),false)),
 ('nigraan_activate_judge_access',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_activate_judge_access' and p.oid=to_regprocedure('public.nigraan_activate_judge_access()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='419b491da86b1b4b8d419bfa71252285')),false)),
 ('nigraan_list_judge_requests',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_list_judge_requests' and p.oid=to_regprocedure('public.nigraan_list_judge_requests()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='2cdb81fcea7f5e3dc5af9c4d57f92239')),false)),
 ('nigraan_retry_judge_email',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_retry_judge_email' and p.oid=to_regprocedure('public.nigraan_retry_judge_email(uuid)') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='d21f764352835aaadb5584dadfc2f44b')),false)),
 ('private_tables',coalesce(((select count(*)=4 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in('nigraan_judge_admins','nigraan_judge_requests','nigraan_judge_audit','nigraan_judge_email_outbox'))),false)),
 ('no_direct_authenticated_writes',coalesce((not exists(select 1 from information_schema.role_table_grants where table_schema='public' and table_name in('nigraan_judge_admins','nigraan_judge_requests','nigraan_judge_audit','nigraan_judge_email_outbox') and grantee in('authenticated','anon','service_role','PUBLIC') and privilege_type in('INSERT','UPDATE','DELETE'))),false)),
 ('review_rpc_no_service_role',coalesce((not has_function_privilege('service_role','public.nigraan_review_judge_access(uuid,text,integer,timestamptz)','EXECUTE')),false)),
 ('review_rpc_no_anonymous',coalesce((not has_function_privilege('anon','public.nigraan_review_judge_access(uuid,text,integer,timestamptz)','EXECUTE')),false)),
 ('review_rpc_authenticated_entry',coalesce((has_function_privilege('authenticated','public.nigraan_review_judge_access(uuid,text,integer,timestamptz)','EXECUTE')),false)),
 ('cycle_event_unique',coalesce((exists(select 1 from pg_constraint where conrelid='public.nigraan_judge_email_outbox'::regclass and conname='nigraan_judge_email_cycle_event_key' and contype='u')),false))
) select case when bool_and(ok) then 'PASS' else 'BLOCKED' end verdict, count(*) filter(where not ok) blocked_checks,coalesce(jsonb_agg(check_name) filter(where not ok),'[]'::jsonb) mismatches from checks;
